def websocket_session(func: typing.Callable[[WebSocket], typing.Awaitable[None]]) -> ASGIApp:
    f: typing.Callable[[WebSocket], typing.Awaitable[None]] = (
        func if is_async_callable(func) else functools.partial(run_in_threadpool, func)  # type: ignore
    )

    async def app(scope: Scope, receive: Receive, send: Send) -> None:
        session = WebSocket(scope, receive, send)

        async def app(scope: Scope, receive: Receive, send: Send) -> None:
            await f(session)

        await wrap_app_handling_exceptions(app, session)(scope, receive, send)

    return app

def __init__(self, path: str, endpoint: typing.Callable[..., typing.Any], *, name: str | None = None, middleware: typing.Sequence[Middleware] | None = None) -> None:
    assert path.startswith("/"), "Routed paths must start with '/'"
    self.path = path
    self.endpoint = endpoint
    self.name = get_name(endpoint) if name is None else name

    endpoint_handler = endpoint
    while isinstance(endpoint_handler, functools.partial):
        endpoint_handler = endpoint_handler.func
    if inspect.isfunction(endpoint_handler) or inspect.ismethod(endpoint_handler):
        self.app = websocket_session(endpoint)
    else:
        self.app = endpoint

    if middleware is not None:
        for cls, args, kwargs in reversed(middleware):
            self.app = cls(self.app, *args, **kwargs)

    self.path_regex, self.path_format, self.param_convertors = compile_path(path)
